void assign_clusters(Point *points, int n, Cluster *clusters, int k) {
    for (int i = 0; i < n; i++) {
        double min_dist = DBL_MAX;
        int best_cluster = -1;
        for (int j = 0; j < k; j++) {
            double d = distance(points[i], clusters[j]);
            if (d < min_dist) {
                min_dist = d;
                best_cluster = j;
            }
        }
        points[i].cluster_id = best_cluster;
        points[i].cluster_distance = min_dist;
    }
}
